#src/nubra_python_sdk/reports/validation.py
import os

from datetime import date as _date, datetime, timedelta, timezone
from typing import Any, ClassVar, FrozenSet, List, Optional

from pydantic import BaseModel, ConfigDict, Field, field_validator, model_validator  # type: ignore

from nubra_python_sdk.reports.reports_enum import ReportActionType, ReportExportFormat


# IST — the backend renders every report date in Asia/Kolkata, so naive dates
# are anchored to IST instead of the caller's local timezone.
IST = timezone(timedelta(hours=5, minutes=30))

def to_ist_datetime(value: Any) -> str:
    """
    Normalise a caller-supplied date into the RFC3339 string the backend expects.

    Accepts ``datetime``, ``date``, or a string (``"2025-04-01"`` or any
    ISO-8601 datetime, with or without an offset). Naive values are treated as
    IST midnight.

    Returns:
        str: e.g. ``"2025-04-01T00:00:00+05:30"``.

    Raises:
        ValueError: If the value is missing or not a parseable date.
    """
    if value is None:
        raise ValueError("a date is required")

    if isinstance(value, datetime):
        parsed = value
    elif isinstance(value, _date):
        parsed = datetime(value.year, value.month, value.day)
    elif isinstance(value, str):
        raw = value.strip()
        if not raw:
            raise ValueError("a date is required")
        try:
            parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
        except ValueError:
            raise ValueError(
                f"invalid date {value!r}; expected 'YYYY-MM-DD' or an ISO-8601 datetime"
            )
    else:
        raise ValueError(
            f"invalid date {value!r}; expected a str, datetime.date or datetime.datetime"
        )

    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=IST)
    return parsed.isoformat()


def _none_to_list(value: Any) -> Any:
    """Go marshals an empty slice as ``null``; treat that as an empty list."""
    return [] if value is None else value


