class _BaseReportRequest(BaseModel):
    """
    Shared behaviour for every report request: date normalisation, date
    ordering, and per-report action-type restrictions.

    Subclasses narrow ``_allowed_actions`` to the actions their endpoint
    actually implements.
    """
    action_type: ReportActionType = ReportActionType.DOWNLOAD

    _allowed_actions: ClassVar[FrozenSet[str]] = frozenset(
        {
            ReportActionType.VIEW.value,
            ReportActionType.DOWNLOAD.value,
            ReportActionType.EMAIL.value,
        }
    )

    model_config = ConfigDict(
        populate_by_name=True,
        use_enum_values=True,
        extra="forbid",
    )

    @field_validator("from_date", "to_date", "date", mode="before", check_fields=False)
    @classmethod
    def _normalize_dates(cls, value: Any) -> str:
        return to_ist_datetime(value)

    @model_validator(mode="after")
    def _check_action_type(self):
        if self.action_type not in self._allowed_actions:
            raise ValueError(
                f"action_type {self.action_type!r} is not supported by this report; "
                f"allowed: {sorted(self._allowed_actions)}"
            )
        return self

    @model_validator(mode="after")
    def _check_date_order(self):
        from_date = getattr(self, "from_date", None)
        to_date = getattr(self, "to_date", None)
        if from_date and to_date:
            if datetime.fromisoformat(from_date) > datetime.fromisoformat(to_date):
                raise ValueError("from_date must not be after to_date")
        return self


class _ExportableReportRequest(_BaseReportRequest):
    """A request whose DOWNLOAD/EMAIL output format is caller-selectable."""
    export_format: ReportExportFormat = ReportExportFormat.PDF

    @model_validator(mode="after")
    def _force_json_for_view(self):
        # The server overrides the back-office export format to JSON for VIEW;
        # mirror that here so the request and the parsed response agree.
        if self.action_type == ReportActionType.VIEW:
            self.export_format = ReportExportFormat.JSON.value
        return self


class DateRangeReportRequest(_ExportableReportRequest):
    """``from_date``/``to_date`` report with a selectable export format."""
    from_date: str
    to_date: str


class SingleDateReportRequest(_ExportableReportRequest):
    """As-on-date report with a selectable export format."""
    date: str


class ExcelDateRangeReportRequest(_BaseReportRequest):
    """
    ``from_date``/``to_date`` report that the server always renders as XLSX
    (dividend, tradebook, trader diary, mutual fund reports). EMAIL is not
    implemented for these endpoints.
    """
    from_date: str
    to_date: str

    _allowed_actions: ClassVar[FrozenSet[str]] = frozenset(
        {ReportActionType.VIEW.value, ReportActionType.DOWNLOAD.value}
    )


class ExcelSingleDateReportRequest(_BaseReportRequest):
    """As-on-date report that the server always renders as XLSX."""
    date: str

    _allowed_actions: ClassVar[FrozenSet[str]] = frozenset(
        {ReportActionType.VIEW.value, ReportActionType.DOWNLOAD.value}
    )


class DownloadOnlyDateRangeRequest(_BaseReportRequest):
    """``from_date``/``to_date`` report that only ever returns a file."""
    from_date: str
    to_date: str

    _allowed_actions: ClassVar[FrozenSet[str]] = frozenset(
        {ReportActionType.DOWNLOAD.value}
    )


