class ReportOption(BaseModel):
    """
    One report the logged-in client may generate.

    Attributes:
        category (Optional[str]): Grouping shown in the UI (see ``ReportCategory``).
        title (Optional[str]): Human readable name.
        type (Optional[str]): Report identifier (see ``ReportType``); the
            ``NubraReports`` docstring maps each one to its method.
        downloadFileTypes (List[str]): Export formats this report supports.
        actionTypes (List[str]): Actions this report supports.
        dateRangeOptions (List[str]): Date pickers this report supports.
        passwordProtected (bool): Whether the downloaded file is password protected.
        password (Optional[str]): Hint for the password (``"PAN"`` means the
            client's PAN in upper case).
        minDate (Optional[str]): Earliest selectable date (``YYYY-MM-DD``).
        maxDate (Optional[str]): Latest selectable date (``YYYY-MM-DD``).
    """
    category: Optional[str] = None
    title: Optional[str] = None
    type: Optional[str] = None
    downloadFileTypes: List[str] = Field(default_factory=list)
    actionTypes: List[str] = Field(default_factory=list)
    dateRangeOptions: List[str] = Field(default_factory=list)
    passwordProtected: bool = False
    password: Optional[str] = None
    minDate: Optional[str] = None
    maxDate: Optional[str] = None

    model_config = ConfigDict(populate_by_name=True, extra="allow")

    @field_validator(
        "downloadFileTypes", "actionTypes", "dateRangeOptions", mode="before"
    )
    @classmethod
    def _default_lists(cls, value: Any) -> Any:
        return _none_to_list(value)


class ReportOptionsResult(BaseModel):
    """The ``res`` payload of ``GET /report``."""
    categories: List[str] = Field(default_factory=list)
    reports: List[ReportOption] = Field(default_factory=list)

    model_config = ConfigDict(populate_by_name=True, extra="allow")

    @field_validator("categories", "reports", mode="before")
    @classmethod
    def _default_lists(cls, value: Any) -> Any:
        return _none_to_list(value)


class ReportOptionsResponse(BaseModel):
    """
    Envelope returned by ``GET /report``. The catalogue is ``res.reports``;
    ``res`` is absent if the backend sends no payload.
    """
    message: Optional[str] = None
    res: Optional[ReportOptionsResult] = None

    model_config = ConfigDict(populate_by_name=True, extra="allow")


