class ReportFile(BaseModel):
    """
    A generated report returned as bytes (``action_type=DOWNLOAD``).

    Attributes:
        content (bytes): Raw file bytes.
        filename (str): Name suggested by the server (``Content-Disposition``),
            or an SDK-generated fallback.
        content_type (str): MIME type reported by the server.
        saved_path (Optional[str]): Where :meth:`save` last wrote the file.
    """
    content: bytes
    filename: str
    content_type: str = "application/octet-stream"
    saved_path: Optional[str] = None

    model_config = ConfigDict(populate_by_name=True)

    def save(self, path: Optional[str] = None) -> str:
        """
        Writes the report to disk.

        Args:
            path (Optional[str]): Target file path, or a directory in which the
                server-suggested :attr:`filename` is used. Defaults to
                :attr:`filename` in the current working directory.

        Returns:
            str: The path written to (also stored on :attr:`saved_path`).
        """
        target = path or self.filename
        if os.path.isdir(target):
            target = os.path.join(target, self.filename)
        parent = os.path.dirname(os.path.abspath(target))
        if parent:
            os.makedirs(parent, exist_ok=True)
        with open(target, "wb") as handle:
            handle.write(self.content)
        self.saved_path = target
        return target


class EmailAck(BaseModel):
    """Acknowledgement returned for ``action_type=EMAIL``."""
    message: Optional[str] = None

    model_config = ConfigDict(populate_by_name=True, extra="allow")


