class BackOfficeAccountMaster(BaseModel):
    """Client identity block present in most back-office report payloads."""
    account_id: Optional[str] = Field(default=None, alias="AccountID")
    account_name: Optional[str] = Field(default=None, alias="AccountName")
    pan_no: Optional[str] = Field(default=None, alias="PANNo")

    model_config = ConfigDict(populate_by_name=True, extra="allow")


class BackOfficeReportView(BaseModel):
    """
    A back-office report rendered as JSON (``action_type=VIEW``).

    The back office returns one key per report section (for example
    ``AccountMaster``, ``LedgerDetail``, ``DividendDetail``), and the exact set
    of sections varies by report and by client data, so only ``AccountMaster``
    is typed. Every other section is kept verbatim under ``extra="allow"`` and
    read through pydantic's own API::

        payload = view.model_dump(by_alias=True, exclude_none=True)
        [k for k, v in payload.items() if isinstance(v, list)]  # section names
        payload.get("LedgerDetail", [])                        # rows of one section
        pandas.DataFrame(payload.get("LedgerDetail", []))       # as a DataFrame

    Attributes:
        AccountMaster (Optional[List[BackOfficeAccountMaster]]): Client identity
            rows, when the report includes them.
    """
    AccountMaster: Optional[List[BackOfficeAccountMaster]] = None

    model_config = ConfigDict(populate_by_name=True, extra="allow")


